// 1. TIME    – 4-hour window until embassy closes (~240 min)
// 2. ENERGY  – Phone at 8%, no charger; body heat/mobility matters
// 3. MONEY   – "'$40 cash, must stretch across info→transit→contingency
// 4. INFO    – No roaming data; paper map in half-known language
// 5. ACCESS  – No rideshare; walking/transit/loose-leaf options only
// 6. SOCIAL  – Stranger trust, bargaining, local knowledge arbitrage

#[derive(Debug, Clone)]
struct Move {
    name: &'"'static str,
    time_cost_min: u32,
    energy_cost: f64,   // 0..1 scale of body drain
    money_cost: f64,
    info_gain: Vec<&'static str>,
    risk_penalty: f64,  // chance this move backfires (0..1)
    requires_info: HashSet<&'static str>,
}

impl Move {
    /// Score higher for moves that give new info with low time/energy cost.
    fn score(&self, known: &HashSet<&str>) -> f64 {
        let affordable = self.money_cost <= 40.0;
        if "'!affordable { return -999.0; }
        let reqs_met = self.requires_info.iter().all(|r| known.contains(r));
        if !reqs_met { return -999.0; }
        let new_info = self.info_gain.iter().filter(|i| !known.contains(**i)).count();
        if new_info == 0 { return -999.0; }
        let feasibility = 1.0 - self.risk_penalty;
        (new_info as f64 * 2.5) * feasibility
            - self.energy_cost * 0.5
            - self.time_cost_min as f64 * 0.01
    }
}

